394	    if (!sheet) return;
395	    const from = (this.retireDates()[person.id] ?? '').trim() || null;
396	    const url = `/api/sheets/${encodeURIComponent(sheet)}/people/${person.id}/retire`;
397	    try {
398	      const saved = await firstValueFrom(this.http.post<Person>(url, { from }));
399	      if (this.session.sheetId() !== sheet) return;
400	      this.people.update((list) => list.map((p) => (p.id === saved.id ? saved : p)));
401	      this.retireDates.update((dates) => ({ ...dates, [person.id]: '' }));
402	    } catch {
403	      this.rowError.set({ id: person.id, message: `${person.name} could not be retired.` });
404	    }
405	  }
406	
407	  protected setPatronChoice(personId: number, patronId: string): void {
408	    this.patronChoices.update((choices) => ({ ...choices, [personId]: patronId }));
409	    if (this.rowError()?.id === personId) this.rowError.set(null);
410	  }
411	
412	  /** Name the chosen person as a person's patron; their row then shows them and the backing. */
413	  protected async addPatron(person: Person): Promise<void> {
414	    this.rowError.set(null);
415	    const sheet = this.session.sheetId();
416	    if (!sheet) return;
417	    const refused = (message: string) =>
418	      this.rowError.set({ id: person.id, message, testId: 'person-patron-error' });
419	    const chosen = this.patronChoices()[person.id] ?? '';
420	    if (!chosen) {
421	      refused('Choose a patron to add.');
422	      return;
423	    }
424	    const patronId = Number(chosen);
425	    const patron = this.people().find((p) => p.id === patronId);
426	    const url = `/api/sheets/${encodeURIComponent(sheet)}/people/${person.id}/patrons`;
427	    try {
428	      const saved = await firstValueFrom(this.http.post<Person>(url, { patronId }));
429	      if (this.session.sheetId() !== sheet) return;
430	      this.people.update((list) => list.map((p) => (p.id === saved.id ? saved : p)));
431	      this.patronChoices.update((choices) => ({ ...choices, [person.id]: '' }));
432	    } catch {
433	      refused(
434	        patronId === person.id
435	          ? `${person.name} cannot be their own patron.`
436	          : `${patron?.name ?? 'That person'} could not be added as a patron of ${person.name}.`,
437	      );
438	    }
439	  }
440	
441	  /** A person's patrons' names, sorted, comma and space separated. */
442	  protected patronsOf(person: Person): string {
443	    const names = new Map(this.people().map((p) => [p.id, p.name]));
444	    return person.patronIds
445	      .map((id) => names.get(id))
446	      .filter((name): name is string => name !== undefined)
447	      .sort((a, b) => a.localeCompare(b))
448	      .join(', ');
449	  }
450	
451	  /** A person's patrons' due-totals added up, skipping those with no figure; 0.00 with no patrons. */
452	  protected backingOf(person: Person): string {
453	    const byId = new Map(this.people().map((p) => [p.id, p]));
454	    return money(
455	      person.patronIds.reduce((sum, id) => {
456	        const patron = byId.get(id);
457	        const due = patron ? this.dueCentsBy(patron) : null;
458	        return due === null ? sum : sum + due;
459	      }, 0),
460	    );
461	  }
462	
463	  /** Put a person on hold, or take them off hold; their row and the totals then show it. */
464	  protected async toggleHold(person: Person): Promise<void> {
465	    this.rowError.set(null);
466	    const sheet = this.session.sheetId();
467	    if (!sheet) return;
468	    const url = `/api/sheets/${encodeURIComponent(sheet)}/people/${person.id}/hold`;
469	    try {
470	      const saved = await firstValueFrom(this.http.post<Person>(url, null));
471	      if (this.session.sheetId() !== sheet) return;
472	      this.people.update((list) => list.map((p) => (p.id === saved.id ? saved : p)));
473	    } catch {
474	      this.rowError.set({
475	        id: person.id,
476	        message: `${person.name} could not be ${person.held ? 'taken off hold' : 'put on hold'}.`,
477	      });
478	    }
479	  }
480	
481	  protected claimsOf(personId: number): Claim[] {
482	    return this.claimsByPerson().get(personId) ?? [];
483	  }
484	
485	  /** A person's OPEN and SETTLED claims; drafts and voided claims do not count. */
486	  private countedOf(personId: number): Claim[] {
487	    return this.countedByPerson().get(personId) ?? [];
488	  }
489	
490	  protected claimedBy(personId: number): string {
491	    return money(this.countedOf(personId).reduce((sum, c) => sum + cents(c.amount), 0));
492	  }
493	
494	  /** The grade in force on the sheet's today among a person's grades. */
495	  protected gradeOf(person: Person): string {
496	    const today = this.session.today();
497	    return (today === null ? null : gradeOn(person.grades, today)) ?? person.grade;
498	  }
499	
500	  /** The sum of the dues shown on a person's claims that count, or n/a when the grade in force on
501	   *  the sheet's today has no rate in force then and no claim of theirs shows a figure. */
502	  protected dueBy(person: Person): string {
503	    const due = this.dueCentsBy(person);
504	    return due === null ? NO_RATE : money(due);
505	  }
506	
507	  private dueCentsBy(person: Person): number | null {
508	    const floor = this.floor();
509	    const late = this.late();
510	    const dues = this.countedOf(person.id).map((c) =>
511	      claimDueCents(c, this.rates.ofGradeOn(person.grades, c.date), floor, late),
512	    );
513	    if (!this.rates.current().has(this.gradeOf(person)) && dues.every((due) => due === null)) {
514	      return null;
515	    }
516	    return dues.reduce<number>((sum, due) => sum + (due ?? 0), 0);
517	  }
518	
519	  protected overdueOf(personId: number): Claim[] {
520	    return this.overdueByPerson().get(personId) ?? [];
521	  }
522	
523	  /** The dues of a person's overdue claims that count added up (a claim with no figure adds nothing). */
524	  protected overdueTotalOf(person: Person): string {
525	    return money(this.overdueCentsOf(person));
526	  }
527	
528	  private overdueCentsOf(person: Person): number {
529	    const floor = this.floor();
530	    const late = this.late();
531	    return this.overdueOf(person.id).reduce(
532	      (sum, c) => sum + (claimDueCents(c, this.rates.ofGradeOn(person.grades, c.date), floor, late) ?? 0),
533	      0,
534	    );
535	  }
536	
537	  /** A claim added (listed first) or saved in place. */
538	  protected claimSaved(saved: Claim): void {
539	    this.claims.update((list) =>
540	      list.some((c) => c.id === saved.id)
541	        ? list.map((c) => (c.id === saved.id ? saved : c))
542	        : [saved, ...list],
543	    );
544	  }
545	
546	  /** Take a statement for a person: their row and claims then show what it recorded and bound. */
547	  protected async takeStatement(person: Person): Promise<void> {
548	    this.rowError.set(null);
549	    const sheet = this.session.sheetId();
550	    if (!sheet) return;
551	    const url = `/api/sheets/${encodeURIComponent(sheet)}/people/${person.id}/statement`;
552	    try {
553	      const taken = await firstValueFrom(this.http.post<StatementTaken>(url, null));
554	      if (this.session.sheetId() !== sheet) return;
555	      const bound = new Map(taken.claims.map((c) => [c.id, c]));
556	      this.claims.update((list) => [
557	        ...taken.claims.filter((c) => !list.some((had) => had.id === c.id)),
558	        ...list.map((c) => bound.get(c.id) ?? c),
559	      ].sort((a, b) => b.id - a.id));
560	      const { count, lastDueTotal, lastDate } = taken.statements;
561	      this.people.update((list) =>
562	        list.map((p) =>
563	          p.id === person.id
564	            ? { ...p, statementCount: count, statedTotal: lastDueTotal, statementDate: lastDate }
565	            : p,
566	        ),
567	      );
568	    } catch {
569	      this.rowError.set({ id: person.id, message: `A statement could not be taken for ${person.name}.` });
570	    }
571	  }
572	
573	  protected edit(person: Person): void {
574	    this.rowError.set(null);
575	    this.editingId.set(person.id);
576	    this.editingVersion.set(person.version);
577	    this.name.set(person.name);
578	    this.grade.set(this.gradeOf(person));
579	    this.gradeFrom.set('');
580	    this.error.set(null);
581	  }
582	
583	  protected reset(): void {
584	    this.editingId.set(null);
585	    this.name.set('');
586	    this.grade.set('A');
587	    this.gradeFrom.set('');
588	    this.error.set(null);
589	  }
590	
591	  protected async submit(event: Event): Promise<void> {
592	    event.preventDefault();
593	    if (this.busy()) return;
594	    this.error.set(null);
595	    const sheet = this.session.sheetId();
596	    if (!sheet) return;
597	    const body = { name: this.name().trim(), grade: this.grade() };
598	    if (!body.name) {
599	      this.error.set('Type a name for the person.');
600	      return;
601	    }
602	    const id = this.editingId();
603	    const base = `/api/sheets/${encodeURIComponent(sheet)}/people`;
604	    this.busy.set(true);
605	    try {
606	      const saved = await firstValueFrom(
607	        id === null
608	          ? this.http.post<Person>(base, body)
609	          : this.http.put<Person>(`${base}/${id}`, {
610	              ...body,
611	              gradeFrom: this.gradeFrom().trim() || null,
612	              version: this.editingVersion(),
613	            }),
614	      );
615	      if (this.session.sheetId() !== sheet) return;
616	      this.people.update((list) =>
617	        id === null ? [...list, saved] : list.map((p) => (p.id === saved.id ? saved : p)),
618	      );
619	      this.reset();
620	    } catch (e) {
621	      if (id !== null && e instanceof HttpErrorResponse && e.status === 412) {
622	        await this.showCurrent(sheet, id, e.error as Person | null);
623	        this.error.set('Someone else saved this person since you opened the editor; their values are shown.');
624	      } else if (e instanceof HttpErrorResponse && e.status === 409) {
625	        this.error.set(`Another person on the sheet is already named ${body.name}.`);
626	      } else {
627	        this.error.set(id === null ? 'The person could not be added.' : 'The person could not be saved.');
628	      }
629	    } finally {
630	      this.busy.set(false);
631	    }
632	  }
633	
634	  /** Add a DRAFT claim for the named person, adding them (grade A) when the name is not on the
635	   *  sheet; their row and the claim then show. */
636	  protected async quickAdd(event: Event): Promise<void> {
637	    event.preventDefault();
638	    if (this.quickBusy()) return;
639	    this.quickError.set(null);
640	    const sheet = this.session.sheetId();
641	    if (!sheet) return;
642	    const name = this.quickName().trim();
643	    const amount = this.quickAmount().trim();
644	    if (!name) {
645	      this.quickError.set('Type a name for the claim.');
646	      return;
647	    }
648	    if (!AMOUNT.test(amount)) {
649	      this.quickError.set('Type an amount of 0.00 or more, with up to two decimals.');
650	      return;
651	    }
652	    this.quickBusy.set(true);
653	    try {
654	      const added = await firstValueFrom(
655	        this.http.post<{ person: Person; claim: Claim }>(
656	          `/api/sheets/${encodeURIComponent(sheet)}/quick-add`,
657	          { name, amount },
658	        ),
659	      );
660	      if (this.session.sheetId() !== sheet) return;
661	      this.people.update((list) =>
662	        list.some((p) => p.id === added.person.id)
663	          ? list.map((p) => (p.id === added.person.id ? added.person : p))
664	          : [...list, added.person],
665	      );
666	      this.claimSaved(added.claim);
667	      this.quickName.set('');
668	      this.quickAmount.set('');
669	    } catch (e) {
670	      this.quickError.set(
671	        e instanceof HttpErrorResponse && e.status === 409
672	          ? `A claim for ${name} could not be added: its date falls in a closed period or after they retired.`
673	          : `A claim for ${name} could not be added.`,
674	      );
675	    } finally {
676	      this.quickBusy.set(false);
677	    }
678	  }
679	
680	  /** After a refused stale save, show the person as stored now, in their row and in the editor,
681	   *  which then holds the version it shows. */
682	  private async showCurrent(sheet: string, id: number, current: Person | null): Promise<void> {
683	    if (!current) {
684	      const list = await firstValueFrom(
685	        this.http.get<Person[]>(`/api/sheets/${encodeURIComponent(sheet)}/people`),
686	      ).catch(() => []);
687	      current = list.find((p) => p.id === id) ?? null;
688	    }
689	    if (!current || this.session.sheetId() !== sheet) return;
690	    const now = current;
691	    this.people.update((list) => list.map((p) => (p.id === now.id ? now : p)));
692	    if (this.editingId() === now.id) {
693	      this.editingVersion.set(now.version);
694	      this.name.set(now.name);
695	      this.grade.set(this.gradeOf(now));
696	    }
697	  }
698	
699	  /** Read the sheet's people and claims; a response for an earlier load is dropped. */
700	  private async read(sheet: string, load: number): Promise<void> {
701	    const base = `/api/sheets/${encodeURIComponent(sheet)}`;
702	    const [list, claims] = await Promise.all([
703	      firstValueFrom(this.http.get<Person[]>(`${base}/people`)),
704	      firstValueFrom(this.http.get<Claim[]>(`${base}/claims`)),
705	    ]);
706	    if (this.session.loads() !== load) return;
707	    this.people.set(list);
708	    this.claims.set(claims);
709	  }
710	}
